-- 자녀를 위한 365일 축복 기도문 (한치호 지음 · 도서출판 두돌비) — 01/21 · 01/31 (2편)
-- 2026-11-17 · 사용자가 붙여 넣은 글자 인식 결과를 Claude 가 교정 (오타 · 이상한 문구만) · IsReviewed = 1
-- 같은 날짜가 이미 있으면 덮어씁니다. 여러 번 실행해도 안전합니다.
SET XACT_ABORT ON;
BEGIN TRAN;

MERGE dbo.Prayer365 AS t
USING (VALUES
('0121', N'믿음의 역사를 이루게 하옵소서', N'살후 1:11',
 N'이러므로 우리도 항상 너희를 위하여 기도함은 우리 하나님이 너희를 그 부르심에 합당한 자로 여기시고 모든 선을 기뻐함과 믿음의 역사를 능력으로 이루게 하시고',
 N'거룩하신 하나님,
날마다 분주히 살아가는 저희에게 쉼의 날을 주시니 감사드립니다. 그리고 저의 아이가 주일이 오기를 기다리면서 지내게 해주심에 감사드립니다. 한 주간의 날들 속에서 한 날을 주일로 구별하여 예배하기를 사모하면서 주일을 기다리게 하셨음을 기뻐합니다. 오늘 저희와 저의 아이가 주님을 영화롭게 해드리기를 소망합니다.
하나님 아버지,
주일이 되면 서둘러 예배당으로 가는 모습이 저희를 흐뭇하게 합니다. 하나님께서 예배하도록 날을 구별하시고 부르셨으니, 마음으로 옷깃을 여며 예배를 드리게 하옵소서. 예배당에 가서 머리를 숙일 때, 감사로 가슴이 뜨거워지게 하옵소서. 겨울의 추운 일기 속에서도 건강을 지켜주시고, 질병에 걸리지 않도록 보호해주셨음에 감사로 찬양을 드리게 하옵소서.
기도를 들으시는 주여,
이 시간에 간절히 비옵는 것은 저의 아이가 예배를 받으시는 하나님께만 집중하기를 원합니다. 자신의 기분을 흥겹게 하기 위해서 찬송을 부르지 않도록 해 주옵소서. 교회에 가서 친구들을 만나는 재미 때문에 이 날을 기다리지 않게 하옵소서. 하나님이 받으시는 예배를 드리는 은혜를 누리기를 원하면서 예수님의 이름으로 기도드립니다. 아멘.',
 N'[{"From":"(실속 1:11)","To":"살후 1:11"},{"From":"미러므로","To":"이러므로"},{"From":"너히물","To":"너희를"},{"From":"너히률 그.부르심예 하당 한","To":"너희를 그 부르심에 합당한"},{"From":"기뻐합과","To":"기뻐함과"},{"From":"쉽의 날","To":"쉼의 날"},{"From":"그 리고","To":"그리고"},{"From":"감사드립 니다","To":"감사드립니다"},{"From":"사모 하면서","To":"사모하면서"},{"From":"하나님아버지,","To":"하나님 아버지,"},{"From":"감사로가 씀이","To":"감사로 가슴이"},{"From":"하읍소서","To":"하옵소서"},{"From":"지켜주시 고","To":"지켜주시고"},{"From":"하읍소 서,","To":"하옵소서."},{"From":"비읍는","To":"비옵는"},{"From":"에배를","To":"예배를"},{"From":"하나님께 만","To":"하나님께만"},{"From":"부 르지","To":"부르지"},{"From":"해 주음소서,","To":"해 주옵소서."},{"From":"않게 하음소서,","To":"않게 하옵소서."},{"From":"에수님의","To":"예수님의"},{"From":"36 자녀를 위한 865일 축복 기도문","To":"(쪽 머리글 — 뺌)"}]'),
('0131', N'생각과 행동을 다스려 주옵소서', N'히 11:6',
 N'믿음이 없이는 기쁘시게 못하나니 하나님께 나아가는 자는 반드시 그가 계신 것과 또한 그가 자기를 찾는 자들에게 상 주시는 이심을 믿어야 할찌니라',
 N'전능하신 하나님,
새해의 삶을 살게 해 주시고, 그 은혜와 사랑으로 보호해 주셨음에 감사드립니다. 저의 아이가 믿음에서 믿음을 더하려는 마음으로 새해의 삶을 시작하게 하시고, 주님의 뜻을 따르려는 결단을 지켜오게 하심에 즐거워합니다. 하나님 앞에서 신앙적인 약속을 한 것을 잘 실천하며 지내왔습니다. 저의 아이의 성장을 통해서 나타나는 영광을 받아주옵소서.
하나님 아버지,
믿음의 사람 아브라함의 신실함을 지니게 하옵소서. 오직 주님만이 자신을 도와주실 하나님으로 믿고, 그 음성에 순종하도록 이끌어 주옵소서. 하나님의 말씀에 갈 바를 알지 못하고도 길을 떠났던 순종의 담대함이 저의 아이의 것이 되기를 소망합니다. 성령님께서 그의 마음을 만져 주시고, 생각과 행동을 다스려 주옵소서. 저의 아이가 자신의 순종을 통해서 하나님을 영화롭게 해드리는 은혜를 체험하도록 하옵소서.
자비로우신 하나님,
하나님의 자녀로서의 복을 누리는 가운데 1월의 마지막 날을 맞이합니다. 저의 아이를 지켜주셔서 은혜 가운데 한 달을 믿음으로 지내온 것에 감사드립니다. 이 달에 행하고자 마음먹은 것들을 잘 해낼 수 있게 도와주신 여호와의 손을 자랑합니다. 내일, 새롭게 시작되는 달에 소망을 품게 해 주시기를 원하면서 예수님의 이름으로 기도드립니다. 아멘.',
 N'[{"From":"(히 11:C)","To":"히 11:6"},{"From":"또하 그가","To":"또한 그가"},{"From":"이식을","To":"이심을"},{"From":"감 사드립니다","To":"감사드립니다"},{"From":"삶 을","To":"삶을"},{"From":"즐 거워합니다","To":"즐거워합니다"},{"From":"지내 왔습니다","To":"지내왔습니다"},{"From":"받아주옵소서. 하나님 아버지,","To":"받아주옵소서. / 하나님 아버지,"},{"From":"자 신을 도외주실","To":"자신을 도와주실"},{"From":"주옵소 서","To":"주옵소서"},{"From":"하나님이 말씀에","To":"하나님의 말씀에"},{"From":"담대함 이","To":"담대함이"},{"From":"다스려 주읍소서","To":"다스려 주옵소서"},{"From":"통 해서","To":"통해서"},{"From":"자비로우신 하나님","To":"자비로우신 하나님,"},{"From":"맞이할 니다","To":"맞이합니다"},{"From":"음해 가운네 한 다음 민음으로","To":"은혜 가운데 한 달을 믿음으로"},{"From":"것 에","To":"것에"},{"From":"미음먹은","To":"마음먹은"},{"From":"해발 수 있게 도 와주신","To":"해낼 수 있게 도와주신"}]')
) AS s (MonthDay, Title, VerseRef, VerseText, Body, Fixes)
ON t.MonthDay = s.MonthDay
WHEN MATCHED THEN UPDATE SET Title = s.Title, VerseRef = s.VerseRef, VerseText = s.VerseText, Body = s.Body, Fixes = s.Fixes,
     IsReviewed = 1, UpdatedAt = DATEADD(HOUR, 9, SYSUTCDATETIME()), UpdatedBy = N'Claude'
WHEN NOT MATCHED THEN INSERT (MonthDay, Title, VerseRef, VerseText, Body, Fixes, IsReviewed, UpdatedAt, UpdatedBy)
     VALUES (s.MonthDay, s.Title, s.VerseRef, s.VerseText, s.Body, s.Fixes, 1, DATEADD(HOUR, 9, SYSUTCDATETIME()), N'Claude');

COMMIT;

SELECT MonthDay, Title, VerseRef, IsReviewed, LEN(Body) AS BodyLen
FROM dbo.Prayer365 WHERE MonthDay IN ('0121', '0131') ORDER BY MonthDay;
